# The pairs are seated, but returning to origin did not trigger completion, so tightening remains necessary.
# Approach red and yellow together to conserve steps before short clockwise turns.
def move_pair(targets, grips, count):
    obs = get_observation()
    s = obs['state']
    starts = {arm: np.array(s[arm + '_ee_pose']) for arm in ['left', 'right']}
    ends = {arm: np.array(targets[arm]) for arm in ['left', 'right']}
    for arm in ['left', 'right']:
        ends[arm][3:] = ends[arm][3:] / np.linalg.norm(ends[arm][3:])
        if np.sum(starts[arm][3:] * ends[arm][3:]) < 0:
            ends[arm][3:] = -ends[arm][3:]
    for i in range(count):
        if control['halted'] or control['remaining'] <= 0:
            break
        t = min(1.0, (i + 1) / max(1, count - 5))
        action = {}
        for arm in ['left', 'right']:
            p = starts[arm] * (1 - t) + ends[arm] * t
            p[3:] = p[3:] / np.linalg.norm(p[3:])
            action[arm + '_ee_pose'] = p
            action[arm + '_ee_joint_state'] = [grips[arm]]
        obs, reward, terminated, truncated, info = step(action)
        control['remaining'] -= 1
        control['halted'] = terminated or truncated
    print('pair', obs['state']['left_ee_pose'], obs['state']['right_ee_pose'], 'remaining', control['remaining'])
    return obs
